window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-d8940f1874c746a3"]={"versions": [{"id": "FIG-d8940f1874c746a3", "releases": ["R23-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Diagrammtyp:</strong> UML-Klassendiagramm (AUTOSAR-Metamodell-Ausschnitt, Foundation / Standardization Template).</li>\n<li><strong>Technischer Zweck:</strong> Definition des Metamodell-Musters zur Deklaration von Gültigkeits- und Konformitätsbereichen (<em>Scopes</em>) für Spezifikationsdokumente und deren Unterelemente im Rahmen des AUTOSAR-Standardisierungs- und Dokumentationsprozesses (MSR/ARXML-Repräsentation).</li>\n<li><strong>Funktionale Einordnung:</strong> Verortet im Foundation-Standard <em>AUTOSAR FO TPS StandardizationTemplate</em>. Es dient der formalen Erfassung, welche Dokumente (z. B. SRS, SWS) und konkreten Dokumentelemente (z. B. Anforderungen, Kapitel) für ein bestimmtes Standard-Profil, Release oder Compliance-Target verbindlich (<code>inScope == true</code>) oder ausgenommen (<code>inScope == false</code>) sind.</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong><code>Identifiable</code></strong> <em>(Basis-Metaklasse, abstrakt)</em>:</li>\n<li>Oberste Abstraktion des AUTOSAR-Metamodells; stellt kanonische Identifikationseigenschaften (<code>shortName</code>, <code>category</code>, <code>uuid</code>) bereit.</li>\n<li><strong><code>CommonPatterns::SpecElementReference</code></strong> <em>(abstrakt)</em>:</li>\n<li>Erbt von: <code>Identifiable</code>.</li>\n<li>Attribute: <code>+ alternativeName: String [0..1]</code> (ermöglicht die Angabe eines abweichenden oder dokumentspezifischen Bezeichners für das referenzierte Element).</li>\n<li><strong><code>CommonPatterns::SpecElementScope</code></strong> <em>(abstrakt)</em>:</li>\n<li>Erbt von: <code>CommonPatterns::SpecElementReference</code>.</li>\n<li>Attribute: <code>+ inScope: Boolean [0..1]</code> (Flag zur expliziten Ein- oder Ausgrenzung des Elements im definierten Geltungsbereich; Standardwert/Semantik regelt Einbezug).</li>\n<li><strong><code>SpecificationScope</code></strong> <em>(Root-Klasse des Musters)</em>:</li>\n<li>Aggregiert über gerichtete Komposition (<code>+specificationDocumentScope</code>, Multiplizität <code>0..*</code>) Instanzen von <code>SpecificationDocumentScope</code>. Bildet den semantischen Container für einen Gesamt-Spezifikationsbereich.</li>\n<li><strong><code>SpecificationDocumentScope</code></strong> <em>(Konkrete Scope-Klasse)</em>:</li>\n<li>Erbt von: <code>CommonPatterns::SpecElementScope</code>.</li>\n<li>Modelliert den Gültigkeitsbereich auf Dokumentebene (z. B. SWS BSW-Modul, TR).</li>\n<li>Aggregiert über gerichtete Komposition (<code>+documentElementScope</code>, Multiplizität <code>0..*</code>) unterlagerte Instanzen von <code>DocumentElementScope</code>.</li>\n<li><strong><code>DocumentElementScope</code></strong> <em>(Konkrete Scope-Klasse)</em>:</li>\n<li>Erbt von: <code>CommonPatterns::SpecElementScope</code>.</li>\n<li>Modelliert den feingranularen Geltungsbereich auf Ebene einzelner Dokumentbestandteile (z. B. SWS-Requirements, Tabellen, Abschnitte).</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\">\n<li><strong>Laufzeit-Dynamik:</strong> Nicht zutreffend (statisches Metamodell-Strukturdiagramm).</li>\n<li><strong>Modell- & Validierungslebenszyklus:</strong></li>\n</ul>\n<ol class=\"fig-list\">\n<li><em>Autorisierungsphase:</em> Toolbasierte Instanziierung von <code>SpecificationScope</code> bei der Definition von Standard-Profilen oder herstellerspezifischen Spezifikations-Teilmengen.</li>\n<li><em>Deklarative Resolution:</em> Parser durchlaufen hierarchisch <code>SpecificationScope</code> $\\rightarrow$ <code>SpecificationDocumentScope</code> $\\rightarrow$ <code>DocumentElementScope</code>.</li>\n<li><em>In-Scope-Auswertung:</em> Ein Element gilt normativ als bindend, wenn <code>inScope = true</code> gesetzt ist (bzw. bei Fehlen des Flags gemäß übergeordnetem Kontext als inkludiert bewertet wird) und übergeordnete Dokument-Scopes die Gültigkeit nicht negieren.</li>\n</ol>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Konformitäts- und Compliance-Tracking (RS_STDT_00102, RS_STDT_00103):</strong></li>\n<li>Entwickler von BSW-Stacks, Safety-Artefakten und Toolchains nutzen diese Scope-Modelle, um automatisierte Traceability-Matrizen und Compliance-Reports (z. B. nach ISO 26262 oder ASPICE) gegen spezifische AUTOSAR-Releases (z. B. R23-11) abzugleichen.</li>\n<li><strong>Filterung für Codegeneratoren und Dokumentations-Pipelines (TPS_STDT_00042, TPS_STDT_00123, TPS_STDT_00187):</strong></li>\n<li>Steuert die automatisierte Extraktion von Anforderungen: Elemente mit <code>inScope == false</code> müssen von nachgelagerten Generatoren (z. B. Requirement-Import für ALM-Tools wie DOORS/PTC oder BSW-Generatoren) ignoriert oder als „out-of-scope“ markiert werden.</li>\n<li><strong>Namensauflösung (<code>alternativeName</code>):</strong></li>\n<li>Erlaubt es Entwicklern und Integratoren, historische oder herstellerspezifische Bezeichner von Dokumentelementen stabil auf kanonische AUTOSAR-Standard-IDs abzubilden, ohne die Metamodell-Identität (<code>shortName</code>) zu brechen.</li>\n</ul>"}, {"id": "FIG-e8e7d920bf942696", "releases": ["R24-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Diagrammtyp:</strong> UML-Klassendiagramm (AUTOSAR-Metamodell-Ausschnitt, Foundation / Standardization Template).</li>\n<li><strong>Technischer Zweck:</strong> Definition des Metamodell-Musters zur Deklaration von Gültigkeits- und Konformitätsbereichen (<em>Scopes</em>) für Spezifikationsdokumente und deren Unterelemente im Rahmen des AUTOSAR-Standardisierungs- und Dokumentationsprozesses (MSR/ARXML-Repräsentation).</li>\n<li><strong>Funktionale Einordnung:</strong> Verortet im Foundation-Standard <em>AUTOSAR FO TPS StandardizationTemplate</em>. Es dient der formalen Erfassung, welche Dokumente (z. B. SRS, SWS) und konkreten Dokumentelemente (z. B. Anforderungen, Kapitel) für ein bestimmtes Standard-Profil, Release oder Compliance-Target verbindlich (<code>inScope == true</code>) oder ausgenommen (<code>inScope == false</code>) sind.</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong><code>Identifiable</code></strong> <em>(Basis-Metaklasse, abstrakt)</em>:</li>\n<li>Oberste Abstraktion des AUTOSAR-Metamodells; stellt kanonische Identifikationseigenschaften (<code>shortName</code>, <code>category</code>, <code>uuid</code>) bereit.</li>\n<li><strong><code>CommonPatterns::SpecElementReference</code></strong> <em>(abstrakt)</em>:</li>\n<li>Erbt von: <code>Identifiable</code>.</li>\n<li>Attribute: <code>+ alternativeName: String [0..1]</code> (ermöglicht die Angabe eines abweichenden oder dokumentspezifischen Bezeichners für das referenzierte Element).</li>\n<li><strong><code>CommonPatterns::SpecElementScope</code></strong> <em>(abstrakt)</em>:</li>\n<li>Erbt von: <code>CommonPatterns::SpecElementReference</code>.</li>\n<li>Attribute: <code>+ inScope: Boolean [0..1]</code> (Flag zur expliziten Ein- oder Ausgrenzung des Elements im definierten Geltungsbereich; Standardwert/Semantik regelt Einbezug).</li>\n<li><strong><code>SpecificationScope</code></strong> <em>(Root-Klasse des Musters)</em>:</li>\n<li>Aggregiert über gerichtete Komposition (<code>+specificationDocumentScope</code>, Multiplizität <code>0..*</code>) Instanzen von <code>SpecificationDocumentScope</code>. Bildet den semantischen Container für einen Gesamt-Spezifikationsbereich.</li>\n<li><strong><code>SpecificationDocumentScope</code></strong> <em>(Konkrete Scope-Klasse)</em>:</li>\n<li>Erbt von: <code>CommonPatterns::SpecElementScope</code>.</li>\n<li>Modelliert den Gültigkeitsbereich auf Dokumentebene (z. B. SWS BSW-Modul, TR).</li>\n<li>Aggregiert über gerichtete Komposition (<code>+documentElementScope</code>, Multiplizität <code>0..*</code>) unterlagerte Instanzen von <code>DocumentElementScope</code>.</li>\n<li><strong><code>DocumentElementScope</code></strong> <em>(Konkrete Scope-Klasse)</em>:</li>\n<li>Erbt von: <code>CommonPatterns::SpecElementScope</code>.</li>\n<li>Modelliert den feingranularen Geltungsbereich auf Ebene einzelner Dokumentbestandteile (z. B. SWS-Requirements, Tabellen, Abschnitte).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\">\n<li><strong>Laufzeit-Dynamik:</strong> Nicht zutreffend (statisches Metamodell-Strukturdiagramm).</li>\n<li><strong>Modell- & Validierungslebenszyklus:</strong></li>\n</ul>\n<ol class=\"fig-list\">\n<li><em>Autorisierungsphase:</em> Toolbasierte Instanziierung von <code>SpecificationScope</code> bei der Definition von Standard-Profilen oder herstellerspezifischen Spezifikations-Teilmengen.</li>\n<li><em>Deklarative Resolution:</em> Parser durchlaufen hierarchisch <code>SpecificationScope</code> $\\rightarrow$ <code>SpecificationDocumentScope</code> $\\rightarrow$ <code>DocumentElementScope</code>.</li>\n<li><em>In-Scope-Auswertung:</em> Ein Element gilt normativ als bindend, wenn <code>inScope = true</code> gesetzt ist (bzw. bei Fehlen des Flags gemäß übergeordnetem Kontext als inkludiert bewertet wird) und übergeordnete Dokument-Scopes die Gültigkeit nicht negieren.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Konformitäts- und Compliance-Tracking (RS_STDT_00102, RS_STDT_00103):</strong></li>\n<li>Entwickler von BSW-Stacks, Safety-Artefakten und Toolchains nutzen diese Scope-Modelle, um automatisierte Traceability-Matrizen und Compliance-Reports (z. B. nach ISO 26262 oder ASPICE) gegen spezifische AUTOSAR-Releases (z. B. R23-11) abzugleichen.</li>\n<li><strong>Filterung für Codegeneratoren und Dokumentations-Pipelines (TPS_STDT_00042, TPS_STDT_00123, TPS_STDT_00187):</strong></li>\n<li>Steuert die automatisierte Extraktion von Anforderungen: Elemente mit <code>inScope == false</code> müssen von nachgelagerten Generatoren (z. B. Requirement-Import für ALM-Tools wie DOORS/PTC oder BSW-Generatoren) ignoriert oder als „out-of-scope“ markiert werden.</li>\n<li><strong>Namensauflösung (<code>alternativeName</code>):</strong></li>\n<li>Erlaubt es Entwicklern und Integratoren, historische oder herstellerspezifische Bezeichner von Dokumentelementen stabil auf kanonische AUTOSAR-Standard-IDs abzubilden, ohne die Metamodell-Identität (<code>shortName</code>) zu brechen.</li>\n</ul>"}], "trans": [{"from": "FIG-d8940f1874c746a3", "to": "FIG-e8e7d920bf942696", "fr": "R23-11", "tr": "R24-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
